def message(language_code: str, key: str) -> str:
    return (
        MESSAGES.get(language_code, {}).get(key)
        or ADDITIONAL_MESSAGES.get(language_code, {}).get(key)
        or DIRECT_ANSWER_MESSAGES.get(language_code, {}).get(key)
        or MESSAGES.get("en", {}).get(key)
        or DIRECT_ANSWER_MESSAGES["en"].get(key)
        or ADDITIONAL_MESSAGES["en"][key]
    )
